import{readFile}from"node:fs/promises";import{EVE_ROUTE_PREFIX}from"#protocol/routes.js";import{join}from"node:path";import{normalizePublicRoutePrefix}from"#shared/public-route-prefix.js";import{atomicWriteFile}from"#shared/atomic-write-file.js";const EVE_CRON_ROUTE_PREFIX=`${EVE_ROUTE_PREFIX}/cron/`;function isRecord(e){return typeof e==`object`&&!!e&&!Array.isArray(e)}function parseOutputConfig(e,t){let n=JSON.parse(e);if(!isRecord(n))throw Error(`Vercel Build Output config at "${t}" must contain a JSON object.`);return n}function readCronConfigs(e,t){if(e.crons!==void 0){if(!Array.isArray(e.crons))throw Error(`Vercel Build Output config at "${t}" must contain a crons array.`);return e.crons.map((e,n)=>{if(!isRecord(e)||typeof e.path!=`string`||!e.path.startsWith(`/`)||typeof e.schedule!=`string`||e.schedule.trim().length===0)throw Error(`Vercel Build Output config at "${t}" contains an invalid cron at index ${n}.`);return e})}}function normalizeCronPath(e,t){return t===void 0||!e.path.startsWith(EVE_CRON_ROUTE_PREFIX)?e:{...e,path:`${t}${e.path}`}}function deduplicateCronConfigs(e){let t=new Set;return e.filter(e=>{let n=`${e.path}\0${e.schedule}`;return t.has(n)?!1:(t.add(n),!0)})}async function normalizeVercelServiceCrons(t){let r=join(t.serviceOutputDirectory,`config.json`),i=parseOutputConfig(await readFile(r,`utf8`),r),a=readCronConfigs(i,r);if(a===void 0)return;let o=normalizePublicRoutePrefix(t.publicRoutePrefix),s=deduplicateCronConfigs(a.map(e=>normalizeCronPath(e,o))),c={...i,crons:s};JSON.stringify(i)!==JSON.stringify(c)&&await atomicWriteFile(r,`${JSON.stringify(c,null,2)}\n`)}export{normalizeVercelServiceCrons};